    if (lbh == RB_INVALID) {
        return RB_INVALID;
    }
    int rbh = validate_subtree(n->right, n, n->key, hi);
    if (rbh == RB_INVALID || rbh != lbh) {
        return RB_INVALID;                      /* propagate, or black-height mismatch */
    }

    return lbh + (n->color == RB_BLACK ? 1 : 0);
