    test_create_basic();
    test_insert_find_single();
    test_find_missing_on_empty();
    test_find_missing_key();
    test_insert_duplicate_overwrites();
    test_insert_many_bst_correctness();
    test_destroy_null_safe();
    test_destroy_frees_everything();
    test_size_tracking();
